  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    attribute previousPressed : Boolean := false;
    perform action tick {
      first start;
      then if io_1 {
        first start;
        then assign previousPressed := io_1;
      } else {
        first start;
        then assign previousPressed := false;
      }
    }
    out attribute io_2 : Real = (if io_1 ? RealFunctions::floor(io_0 * 255.0 / 1023.0) else 0.0);
  }
  part system : Controller;
}
